INSERT INTO documents (id, owner_id, title, content, version, created_at, updated_at, updated_by) VALUES ('d_welcome', 'u_alice', 'Welcome to Ajaia Docs', '{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Welcome to Ajaia Docs"}]},{"type":"paragraph","content":[{"type":"text","text":"This document belongs to Alice. Bob can "},{"type":"text","text":"edit","marks":[{"type":"bold"}]},{"type":"text","text":" it and Carol can only "},{"type":"text","text":"view","marks":[{"type":"italic"}]},{"type":"text","text":" it. Sign in as each of them to see the difference."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Things to try"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Format some text with the toolbar, then refresh the page."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Import a "},{"type":"text","text":".docx","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":".md","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":".txt","marks":[{"type":"bold"}]},{"type":"text","text":" file from the document list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Share a document from the "},{"type":"text","text":"Share","marks":[{"type":"underline"}]},{"type":"text","text":" button and pick a role."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What to expect"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changes save on their own a moment after you stop typing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Viewers see the document but cannot change it. The server enforces this, not only the page."}]}]}]}]}', 1, 1794528000000, 1794528000000, 'u_alice');
